insert into public.terms (id, word, pair, meaning, examples, register, domain, lang, added_by) values
('t-im-easy', 'I''m easy', '난 아무거나 괜찮아', '고르는 걸 상대에게 맡길 때 쓰는 구어. ''나는 쉽다''가 아니에요.', '[{"s":"Honestly, I''m easy. Pick whatever''s closest to you.","t":"난 진짜 아무 데나 괜찮아. 너 가까운 데로 골라."},{"s":"Pizza or tacos? I''m easy.","t":"피자든 타코든 난 상관없어."},{"s":"\"Window or aisle?\" \"I''m easy, you choose.\"","t":"\"창가 자리, 통로 자리?\" \"난 아무 데나 괜찮아, 네가 골라.\""},{"s":"I''m easy about the time. Whatever works for you.","t":"시간은 아무 때나 괜찮아. 너 편한 때로 해."}]'::jsonb, '구어', '일반', 'en', null),
('t-on-the-house', 'on the house / on us', '가게가 대접하다, 무료로 드리다', '가게가 값을 받지 않고 내는 것. 광고에서는 free보다 대접하는 느낌이 살아요.', '[{"s":"Pick a book, and the coffee''s on us.","t":"책 한 권을 고르면 커피는 저희가 내려 드려요."},{"s":"Dessert is on the house tonight.","t":"오늘 디저트는 서비스예요."},{"s":"Your first class is on us.","t":"첫 수업은 무료로 드려요."},{"s":"Sorry for the wait. The drinks are on the house.","t":"오래 기다리시게 해서 죄송해요. 음료는 서비스로 드릴게요."}]'::jsonb, '구어', '마케팅·브랜드', 'en', null),
('t-on-track', 'on track', '순조롭게 진행 중인', '계획한 일정·목표대로 가고 있다는 뜻. ''트랙 위에''가 아니에요.', '[{"s":"We''re on track to launch by the end of the month.","t":"이달 말 출시 일정대로 순조롭게 진행 중입니다."},{"s":"The project is back on track after last week''s delay.","t":"지난주에 늦어졌던 프로젝트가 다시 제 궤도에 올랐어요."},{"s":"Are we still on track for Friday?","t":"금요일 일정은 여전히 문제없나요?"},{"s":"Sales are on track to beat last year''s numbers.","t":"매출은 작년 실적을 넘어설 흐름이에요."}]'::jsonb, '문어', '비즈니스·IR', 'en', null),
('t-something-came-up', 'Something has come up', '갑작스러운 일이 생겨서', '이유를 자세히 밝히지 않고 사정이 생겼다고 알리는 정형 표현이에요.', '[{"s":"Something has come up. Could we move this afternoon''s call to tomorrow?","t":"갑작스러운 일이 생겨서요. 오늘 오후 통화를 내일로 옮길 수 있을까요?"},{"s":"Sorry, something came up and I can''t make it tonight.","t":"미안, 일이 생겨서 오늘 저녁엔 못 가."},{"s":"Something urgent has come up at home.","t":"집에 급한 일이 생겼어요."},{"s":"If anything comes up, just let me know.","t":"무슨 일 생기면 알려 줘."}]'::jsonb, '구어', '비즈니스·IR', 'en', null),
('t-flag', 'flag', '알려 주다, 짚어 주다', '문제나 확인할 점을 상대에게 알려 주는 것. ''깃발을 달다''가 아니에요.', '[{"s":"Thanks for flagging this. We''re looking into it.","t":"알려 주셔서 감사합니다. 지금 확인하고 있습니다."},{"s":"Please flag any typos before we send it out.","t":"보내기 전에 오타가 있으면 짚어 주세요."},{"s":"Just flagging that the deadline has moved to Monday.","t":"참고로 마감이 월요일로 바뀌었어요."},{"s":"The system flagged the payment as suspicious.","t":"시스템이 그 결제를 의심 거래로 표시했어요."}]'::jsonb, '구어', '비즈니스·IR', 'en', null),
('t-sleep-on-it', 'sleep on it', '하룻밤 자고 생각해 보다', '결정을 바로 내리지 않고 하루쯤 두고 차분히 생각하는 것.', '[{"s":"You don''t have to decide tonight. Sleep on it.","t":"오늘 밤에 정할 필요 없어. 하룻밤 자고 생각해 봐."},{"s":"Let me sleep on it and get back to you tomorrow.","t":"하루 생각해 보고 내일 답드릴게요."},{"s":"It''s a big offer. I''d sleep on it if I were you.","t":"큰 제안이잖아. 나라면 하룻밤 생각해 볼 것 같아."},{"s":"I slept on it, and I think we should go ahead.","t":"하룻밤 생각해 봤는데, 진행하는 게 좋겠어요."}]'::jsonb, '구어', '일반', 'en', null),
('t-yanghae', '양해 부탁드립니다', '이해해 주세요 → 양해를 구합니다 → 양해 부탁드립니다', 'We appreciate your understanding (공지·안내문의 정중한 사과·부탁)', '[{"s":"원자재 가격 상승으로 다음 달부터 단가를 5% 조정하게 되었습니다. 양해 부탁드립니다.","t":"Due to rising material costs, we will be adjusting our unit prices by 5% starting next month. We appreciate your understanding."},{"s":"공사 기간 중 소음이 발생할 수 있으니 양해 부탁드립니다.","t":"There may be some noise during construction. Thank you for your patience."},{"s":"사정상 오늘은 일찍 문을 닫습니다. 너른 양해 부탁드립니다.","t":"We are closing early today due to unforeseen circumstances. We appreciate your understanding."},{"s":"답변이 늦어진 점 양해 부탁드립니다.","t":"Apologies for the delayed reply."}]'::jsonb, '문어', '공문·행정', 'ko', null),
('t-mola-boda', '몰아 보다', '이어서 보다 → 몰아 보다 → 정주행하다', 'binge-watch (드라마·시리즈를 한꺼번에 이어 보다)', '[{"s":"별거 없어. 그냥 집에서 드라마 몰아 보려고.","t":"Nothing much. Just gonna stay in and binge a show."},{"s":"주말 내내 시즌 1을 몰아 봤어.","t":"I binge-watched the whole first season over the weekend."},{"s":"그 시리즈 정주행하느라 밤샜어.","t":"I stayed up all night bingeing that series."},{"s":"한 번에 몰아 보는 것보다 한 편씩 아껴 보는 게 좋아.","t":"I''d rather savor it one episode at a time than binge it all at once."}]'::jsonb, '구어', '일반', 'ko', null)
